gint;						// resourceID - the type of resource, may be '****' for wildcard		integer;						// IDOffset - the offset to add to ID for resources that support this script	};		// Direct resource mapping table.	integer = $$CountOf(DirectMap); 	// Entry count	wide array DirectMap	{		longint;						// fromType - type to map from (often STR#)		integer;						// fromID - rsrc ID of the resource to map from		integer;						// fromIndex - index of the item desired		integer;						// toID - rsrc ID of the resource to map to		integer;						// toIndex - replacement index to use	};};#endif